import ast, json, re, html, math

class Undefined:
    def __init__(self,name=''): self.name=name
    def __getattr__(self,k): return Undefined(self.name+'.'+k)
    def __getitem__(self,k): return Undefined(self.name)
    def __str__(self): return ''
    def __repr__(self): return ''
    def __bool__(self): return False
    def __iter__(self): return iter(())
    def __eq__(self,o): return isinstance(o,Undefined) or o is None
    def __ne__(self,o): return not self==o
    def __getattr__(self,k): return self

class Safe(str): pass

def truth(x): return bool(x)
def repr_value(x):
    if isinstance(x,Undefined): return ''
    if isinstance(x,bool): return str(x).lower()
    if x is None:return 'none'
    if isinstance(x,str):return x
    if isinstance(x,(list,tuple)):return '['+', '.join(repr_value(v) for v in x)+']'
    if isinstance(x,dict):return '{'+', '.join(repr_value(k)+': '+repr_value(v) for k,v in x.items())+'}'
    return str(x)
def escape(x,mode):
