            elif fmt == "yaml": obj = parse_yaml(text)
            elif fmt == "querystring":
                pairs = parse_qs(text, keep_blank_values=True)
                dup = next((k for k, v in pairs.items() if len(v) > 1), None)
                if dup is not None: raise ValueError(f'Multiple values for one key: "{dup}"')
                obj = {k: v[0] for k, v in pairs.items()}
